function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 3000) return 's needs 1 to 3000 letters.';
  if (!/^[a-z]+$/.test(s)) return 's uses lowercase English letters only.';
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is a whole number from 1 to s.length.';
  return null;
}

