function numberOfSubstrings(s, k) {
  // Grow every substring from each start, keeping its letter counts and the largest count so far.
  let result = 0;
  for (let i = 0; i < s.length; i++) {
    const seen = new Map();
    let most = 0;
    for (let j = i; j < s.length; j++) {
      const times = (seen.get(s[j]) || 0) + 1;
      seen.set(s[j], times);
      most = Math.max(most, times);
      if (most >= k) result++;
    }
  }
  return result;
}

