function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 14);
  // Few distinct letters make repeats common; all 26 make them rare, so qualifying substrings must be long.
  const letters = [1, 2, 3, 5, 26][Math.floor(rand() * 5)];
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  const k = rand() < 0.1 ? n : 1 + Math.floor(rand() * Math.min(n, large ? 150 : 5));
  return [s, k];
}
